bool utf8(string s){int rem=0;unsigned cp=0,mincp=0;for(unsigned char c:s){if(!rem){if(c<128)continue;if(c>=0xc2&&c<=0xdf){rem=1;cp=c&31;mincp=128;}else if(c>=0xe0&&c<=0xef){rem=2;cp=c&15;mincp=2048;}else if(c>=0xf0&&c<=0xf4){rem=3;cp=c&7;mincp=65536;}else return false;}else{if((c&0xc0)!=0x80)return false;cp=(cp<<6)|(c&63);if(!--rem&&(cp<mincp||cp>0x10ffff||(cp>=0xd800&&cp<=0xdfff)))return false;}}return !rem;}
int pathnorm(string target,string &path,string &query){if(target.empty()||target[0]!='/'||target.find('#')!=string::npos)return 400;auto q=target.find('?');string a=target.substr(0,q);if(q!=string::npos)query=target.substr(q);string dec;for(size_t i=0;i<a.size();i++){unsigned char c=a[i];if(c=='%'){if(i+2>=a.size()||!isxdigit((unsigned char)a[i+1])||!isxdigit((unsigned char)a[i+2]))return 400;auto hex=[](char x){return isdigit((unsigned char)x)?x-'0':tolower(x)-'a'+10;};c=hex(a[i+1])*16+hex(a[i+2]);i+=2;}if(c==0||c=='\\')return 400;dec+=c;}if(!utf8(dec))return 400;bool trail=dec.size()>1&&dec.back()=='/';stringstream ss(dec);string part;path="/";bool first=true;while(getline(ss,part,'/')){if(part=="..")return 403;if(part.empty()||part==".")continue;if(!first)path+='/';first=false;path+=part;}if(trail&&path.back()!='/')path+='/';return 0;}
int selectServer(Endpoint &ep,Req&r){int cnt=count(r,"host");if(cnt==0)return r.version=="HTTP/1.0"?ep.def:-1;if(cnt!=1)return -1;string h=lower(geth(r,"host"));auto c=h.find(':');if(c!=string::npos){string p=h.substr(c+1);auto n=number(p);if(n<1||n>65535)return -1;h.resize(c);}if(!dns(h))return -1;for(int i:ep.servers)for(auto &n:cfg.servers[i].names)if(n==h)return i;return -1;}
int openconfined(string root,string rel,struct stat &st){int fd=open(root.c_str(),O_RDONLY|O_DIRECTORY|O_CLOEXEC);if(fd<0)return -1;stringstream ss(rel);string x;vector<string> parts;while(getline(ss,x,'/'))if(!x.empty())parts.push_back(x);for(size_t i=0;i<parts.size();i++){int next=openat(fd,parts[i].c_str(),O_RDONLY|O_NOFOLLOW|O_CLOEXEC|(i+1<parts.size()?O_DIRECTORY:0));int e=errno;close(fd);if(next<0){errno=e;return -1;}fd=next;}if(fstat(fd,&st)){close(fd);return -1;}return fd;}
void local(IO &io,Req &r,Location &l,string path,string query,bool closeconn){if(r.method!="GET"&&r.method!="HEAD"){sendhead(io,405,0,closeconn);return;}if(count(r,"transfer-encoding")||count(r,"content-length")>1||(count(r,"content-length")&&(number(geth(r,"content-length"))!=0))){sendhead(io,400,0,true);return;}if(l.ret){sendhead(io,l.ret,0,closeconn,"Location: "+l.dest+"\r\n");return;}string rel=l.alias.empty()?path:path.substr(l.path.size());string root=l.alias.empty()?l.st.root:l.alias;struct stat st{};int fd=openconfined(root,rel,st);if(fd<0){int code=(errno==ELOOP||errno==EACCES)?403:404;sendhead(io,code,0,closeconn);return;}if(S_ISDIR(st.st_mode)){if(path.back()!='/'){close(fd);sendhead(io,301,0,closeconn,"Location: "+path+"/"+query+"\r\n");return;}int found=-1;for(auto &name:l.st.index){int f=openat(fd,name.c_str(),O_RDONLY|O_NOFOLLOW|O_CLOEXEC);if(f>=0){struct stat t{};if(!fstat(f,&t)&&S_ISREG(t.st_mode)){found=f;st=t;rel+=name;break;}close(f);}}close(fd);fd=found;if(fd<0){sendhead(io,403,0,closeconn);return;}}else if(!S_ISREG(st.st_mode)||path.back()=='/'){close(fd);sendhead(io,403,0,closeconn);return;}string et="\""+to_string((long long)st.st_mtime)+"-"+to_string((long long)st.st_size)+"\"";string extra;if(l.st.etag){extra+="ETag: "+et+"\r\n";string inm=geth(r,"if-none-match");if(inm=="*"||inm==et){close(fd);sendhead(io,304,0,closeconn,extra);return;}}string ext;auto dot=rel.find_last_of('.');if(dot!=string::npos)ext=lower(rel.substr(dot+1));string typ=l.st.types.count(ext)?l.st.types.at(ext):l.st.def;extra+="Content-Type: "+typ+"\r\n";long long start=0,end=st.st_size-1;int code=200;string range=geth(r,"range");if(!range.empty()){bool bad=range.rfind("bytes=",0)!=0||range.find(',')!=string::npos;string v=bad?"":range.substr(6);auto d=v.find('-');if(d==string::npos||v.find('-',d+1)!=string::npos)bad=true;string a=bad?"":v.substr(0,d),b=bad?"":v.substr(d+1);if((a.empty()&&b.empty())||(!a.empty()&&!digits(a))||(!b.empty()&&!digits(b)))bad=true;if(bad){close(fd);sendhead(io,400,0,true);return;}long long x=a.empty()?-1:number(a),y=b.empty()?-1:number(b);if((!a.empty()&&x<0)||(!b.empty()&&y<0)){close(fd);sendhead(io,400,0,true);return;}if(a.empty()){start=max(0LL,(long long)st.st_size-y);if(y==0)start=st.st_size;}else{start=x;if(!b.empty())end=min(end,y);}if(start>=st.st_size||start>end){close(fd);sendhead(io,416,0,closeconn,extra+"Content-Range: bytes */"+to_string(st.st_size)+"\r\n");return;}code=206;extra+="Content-Range: bytes "+to_string(start)+"-"+to_string(end)+"/"+to_string(st.st_size)+"\r\n";}long long len=end-start+1;if(sendhead(io,code,len,closeconn,extra)&&r.method!="HEAD"){lseek(fd,start,SEEK_SET);char buf[32768];while(len>0){ssize_t n=read(fd,buf,min((long long)sizeof(buf),len));if(n<=0||!io.wr(buf,n))break;len-=n;}}close(fd);}
void proxy(IO &io,Req &r,Location &l,string path,string query,bool closeconn,string &pending){if(r.method!="GET"&&r.method!="HEAD"&&r.method!="POST"){sendhead(io,405,0,closeconn);return;}if(count(r,"content-length")>1||count(r,"transfer-encoding")||number(geth(r,"content-length"),0)<0){sendhead(io,400,0,true);return;}long long body=number(geth(r,"content-length"),0);if(body>cfg.body){sendhead(io,413,0,true);return;}auto it=find_if(cfg.ups.begin(),cfg.ups.end(),[&](auto &u){return u.name==l.proxy;});if(it==cfg.ups.end()){sendhead(io,502,0,true);return;}int port=it->ports[it->next++%it->ports.size()];int fd=socket(AF_INET,SOCK_STREAM,0);timeval tv{10,0};setsockopt(fd,SOL_SOCKET,SO_RCVTIMEO,&tv,sizeof(tv));setsockopt(fd,SOL_SOCKET,SO_SNDTIMEO,&tv,sizeof(tv));sockaddr_in a{};a.sin_family=AF_INET;a.sin_addr.s_addr=htonl(INADDR_LOOPBACK);a.sin_port=htons(port);if(connect(fd,(sockaddr*)&a,sizeof(a))<0){close(fd);sendhead(io,502,0,true);return;}IO up{fd};string target=l.uri.empty()?r.target:l.uri+path.substr(l.path.size())+query;string h=r.method+" "+target+" HTTP/1.1\r\nHost: 127.0.0.1:"+to_string(port)+"\r\nConnection: close\r\n";string conn=geth(r,"connection");for(auto &v:r.h)if(v.first!="host"&&v.first!="connection"&&v.first!="proxy-connection"&&v.first!="keep-alive"&&v.first!="transfer-encoding"&&v.first!="upgrade"&&!hasToken(conn,v.first))h+=v.first+": "+v.second+"\r\n";h+="\r\n";if(!up.wr(h)){close(fd);sendhead(io,502,0,true);return;}char buf[32768];while(body>0){if(!pending.empty()){size_t n=min((long long)pending.size(),body);if(!up.wr(pending.data(),n)){close(fd);return;}pending.erase(0,n);body-=n;}else{int n=io.rd(buf,min((long long)sizeof(buf),body));if(n<=0||!up.wr(buf,n)){close(fd);return;}body-=n;}}string head;while(head.find("\r\n\r\n")==string::npos&&head.size()<(size_t)cfg.headerbytes){int n=up.rd(buf,sizeof(buf));if(n<=0){close(fd);sendhead(io,502,0,true);return;}head.append(buf,n);}auto p=head.find("\r\n\r\n");if(p==string::npos){close(fd);sendhead(io,502,0,true);return;}string rest=head.substr(p+4),raw=head.substr(0,p+4);auto line=raw.find("\r\n");int status=line==string::npos?0:number(raw.substr(9,3),0);if(status<200||status>599){close(fd);sendhead(io,502,0,true);return;}vector<pair<string,string>> fields;size_t off=line+2;long long len=-1;bool chunk=false;string ex;while(off<p){auto e=raw.find("\r\n",off);string s=raw.substr(off,e-off);auto c=s.find(':');if(c==string::npos||!token(s.substr(0,c))){close(fd);sendhead(io,502,0,true);return;}string k=lower(s.substr(0,c)),v=trim(s.substr(c+1));fields.emplace_back(k,v);if(k=="content-length"){if(len!=-1||!digits(v)||(len=number(v))<0){close(fd);sendhead(io,502,0,true);return;}}if(k=="transfer-encoding")chunk=lower(v)=="chunked";off=e+2;}for(auto &kv:fields)if(kv.first!="content-length"&&kv.first!="transfer-encoding"&&kv.first!="connection"&&kv.first!="keep-alive")ex+=kv.first+": "+kv.second+"\r\n";bool bodyless=r.method=="HEAD"||status==204||status==304;if(chunk||len<0)closeconn=true;if(chunk)ex+="Transfer-Encoding: chunked\r\n";if(!sendhead(io,status,status==204?-1:len,closeconn,ex)){close(fd);return;}if(!bodyless){if(len>=0){size_t n=min((long long)rest.size(),len);if(n&&!io.wr(rest.data(),n)){close(fd);return;}len-=n;while(len>0){int z=up.rd(buf,min((long long)sizeof(buf),len));if(z<=0||!io.wr(buf,z))break;len-=z;}}else{if(!rest.empty())io.wr(rest);int z;while((z=up.rd(buf,sizeof(buf)))>0)if(!io.wr(buf,z))break;}}close(fd);}
void serve(int fd,Endpoint *ep){timeval tv{10,0};setsockopt(fd,SOL_SOCKET,SO_RCVTIMEO,&tv,sizeof(tv));setsockopt(fd,SOL_SOCKET,SO_SNDTIMEO,&tv,sizeof(tv));IO io{fd};if(ep->tls){io.ssl=SSL_new(cfg.servers[ep->def].ctx);SSL_set_fd(io.ssl,fd);if(SSL_accept(io.ssl)!=1){SSL_free(io.ssl);close(fd);return;}}string pending;int requests=0;for(;;){while(pending.find("\r\n\r\n")==string::npos){if(pending.size()>(size_t)cfg.headerbytes){sendhead(io,431,0,true);goto done;}char b[8192];int n=io.rd(b,sizeof(b));if(n<=0)goto done;pending.append(b,n);}size_t end=pending.find("\r\n\r\n")+4;if(end>(size_t)cfg.headerbytes){sendhead(io,431,0,true);break;}Req r;if(!parseReq(pending.substr(0,end),r)){sendhead(io,400,0,true);break;}pending.erase(0,end);int si=selectServer(*ep,r);if(si<0){sendhead(io,400,0,true);break;}auto &s=cfg.servers[si];if(count(r,"expect")){sendhead(io,417,0,true);break;}string path,q;int err=pathnorm(r.target,path,q);if(err){sendhead(io,err,0,true);break;}Location *loc=nullptr;for(auto &l:s.locs){if(l.exact&&l.path==path){loc=&l;break;}if(!l.exact&&path.rfind(l.path,0)==0&&(!loc||l.path.size()>loc->path.size()))loc=&l;}if(!loc){sendhead(io,404,0,true);break;}bool cl=r.version=="HTTP/1.0"||hasToken(geth(r,"connection"),"close")||++requests>=loc->st.keep||loc->st.idle==0;if(loc->proxy.empty())local(io,r,*loc,path,q,cl);else {proxy(io,r,*loc,path,q,true,pending);cl=true;}if(cl)break;}done:if(io.ssl){SSL_shutdown(io.ssl);SSL_free(io.ssl);}close(fd);}
volatile sig_atomic_t stopping=0,reloadflag=0;void term(int){stopping=1;}void hup(int){reloadflag=1;}
void worker(){signal(SIGTERM,term);signal(SIGHUP,SIG_IGN);signal(SIGPIPE,SIG_IGN);vector<pollfd> pf;for(auto &e:cfg.endpoints)pf.push_back({e.fd,POLLIN,0});while(!stopping){int n=poll(pf.data(),pf.size(),200);if(n<=0)continue;for(size_t i=0;i<pf.size();i++)if(pf[i].revents&POLLIN){int fd=accept4(pf[i].fd,nullptr,nullptr,SOCK_CLOEXEC);if(fd>=0){serve(fd,&cfg.endpoints[i]);}}}_exit(0);}
int main(int argc,char **argv){signal(SIGPIPE,SIG_IGN);if(argc!=3||(string(argv[1])!="--config"&&string(argv[1])!="--check-config")){fprintf(stderr,"usage: server --config PATH\n");return 1;}try{parseconfig(argv[2]);if(string(argv[1])=="--check-config")return 0;for(auto &e:cfg.endpoints){if(e.tls)for(int i:e.servers){SSL_CTX_set_tlsext_servername_callback(cfg.servers[i].ctx,sni_cb);SSL_CTX_set_tlsext_servername_arg(cfg.servers[i].ctx,&e);SSL_CTX_set_alpn_select_cb(cfg.servers[i].ctx,alpn_cb,nullptr);}e.fd=socket(AF_INET,SOCK_STREAM|SOCK_CLOEXEC,0);int one=1;setsockopt(e.fd,SOL_SOCKET,SO_REUSEADDR,&one,sizeof(one));sockaddr_in a{};a.sin_family=AF_INET;a.sin_addr.s_addr=htonl(INADDR_LOOPBACK);a.sin_port=htons(e.port);if(bind(e.fd,(sockaddr*)&a,sizeof(a))||listen(e.fd,1024))fail("cannot bind listener");}signal(SIGTERM,term);signal(SIGINT,term);signal(SIGHUP,hup);vector<pid_t> workers;auto spawn=[&](){pid_t p=fork();if(p==0)worker();if(p>0)workers.push_back(p);};for(int i=0;i<cfg.workers;i++)spawn();while(!stopping){int st;pid_t p=waitpid(-1,&st,WNOHANG);if(p>0){workers.erase(remove(workers.begin(),workers.end(),p),workers.end());spawn();}else usleep(100000);if(reloadflag){reloadflag=0;}}for(auto p:workers)kill(p,SIGTERM);for(auto p:workers)waitpid(p,nullptr,0);return 0;}catch(exception &e){fprintf(stderr,"%s\n",e.what());return 1;}}
